/* @lc app=leetcode id=2266 lang=kotlin */ class Solution { fun countTexts(pressedKeys: String): Int = LongArray(pressedKeys.length + 1).apply { this[0] = 1 }.also { dp -> (1..pressedKeys.length).forEach { i -> (1..(if (pressedKeys[i - 1] in "79") 4 else 3)).takeWhile { k -> i - k >= 0 && pressedKeys[i - 1] == pressedKeys[i - k] }.forEach { k -> dp[i] = (dp[i] + dp[i - k]) % 1000000007 } } }.let { it[pressedKeys.length].toInt() } }